import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Notification> inbox = new ArrayList<>();
        inbox.add(new EmailNotification("ada@example.com", "Your order shipped"));
        inbox.add(new SmsNotification("555-0101", "Your code is 4821"));
        inbox.add(new SmsNotification("555-0199", "Your table is ready"));

        int smsCount = 0;
        for (Notification n : inbox) {
            System.out.println(n.send());
